//! `mzizi-css`: builds the pattern stylesheets with Lightning CSS (issue #708).
//!
//! The sources live in `styles/pattern/`: `tokens.css` (values only, generated by
//! `scripts/generate-pattern-tokens.mjs`), `floor.css` (the identity-neutral minimums) and
//! `mzizi-theme.css` (the Mzizi look). Lightning CSS lowers nesting and `color-mix()` for
//! the browser targets below, and minifies. The output goes to `styles/pattern/dist/`.
//!
//! `mzizi-css build` writes the minified files. `mzizi-css --check` builds in memory and
//! fails when a committed file under `dist/` differs from what the sources produce, so CI
//! fails on a stale bundle the same way the generators' `--check` modes do.

use std::fs;
use std::path::{Path, PathBuf};
use std::process::ExitCode;

use lightningcss::stylesheet::{ParserOptions, PrinterOptions, StyleSheet};
use lightningcss::targets::{Browsers, Targets};

/// The stylesheets to build, source name and output name.
const SHEETS: [(&str, &str); 3] = [
    ("tokens.css", "tokens.min.css"),
    ("floor.css", "floor.min.css"),
    ("mzizi-theme.css", "mzizi-theme.min.css"),
];

/// Browser floor: the first versions with `color-mix()`, nesting and `:is()` in the
/// shipped engines. Older targets get Lightning CSS's lowered output instead.
fn targets() -> Targets {
    Targets {
        browsers: Some(Browsers {
            chrome: Some(111 << 16),
            edge: Some(111 << 16),
            firefox: Some(113 << 16),
            safari: Some((16 << 16) | (2 << 8)),
            ..Browsers::default()
        }),
        ..Targets::default()
    }
}

/// Minify one source file.
fn build_one(source: &str, name: &str) -> Result<String, String> {
    let sheet = StyleSheet::parse(
        source,
        ParserOptions {
            filename: name.to_owned(),
            ..ParserOptions::default()
        },
    )
    .map_err(|e| format!("{name}: parse error: {e}"))?;
    let out = sheet
        .to_css(PrinterOptions {
            minify: true,
            targets: targets(),
            ..PrinterOptions::default()
        })
        .map_err(|e| format!("{name}: print error: {e}"))?;
    Ok(format!("{}\n", out.code))
}

/// The `styles/pattern` directory of this checkout.
fn pattern_dir() -> PathBuf {
    Path::new(env!("CARGO_MANIFEST_DIR")).join("../../../styles/pattern")
}

/// What the command line asked for: build (no arguments) or `--check`.
/// Anything else is refused, so a mistyped `--check` in CI cannot fall
/// through to build mode and pass.
fn parse_mode<I: IntoIterator<Item = String>>(args: I) -> Result<bool, String> {
    let args: Vec<String> = args.into_iter().collect();
    match args.as_slice() {
        [] => Ok(false),
        [flag] if flag == "--check" => Ok(true),
        _ => Err(format!(
            "mzizi-css: unexpected arguments {args:?}; usage: mzizi-css [--check]"
        )),
    }
}

fn main() -> ExitCode {
    // nosemgrep: rust.lang.security.args.args -- reads this build tool's own flag; argv[0] is skipped and nothing security-relevant depends on it.
    let check = match parse_mode(std::env::args().skip(1)) {
        Ok(check) => check,
        Err(e) => {
            eprintln!("{e}");
            return ExitCode::from(2);
        }
    };
    let dir = pattern_dir();
    let dist = dir.join("dist");
    let mut drift = Vec::new();

    for (source, output) in SHEETS {
        let src_path = dir.join(source);
        let source_text = match fs::read_to_string(&src_path) {
            Ok(t) => t,
            Err(e) => {
                eprintln!("mzizi-css: cannot read {}: {e}", src_path.display());
                return ExitCode::FAILURE;
            }
        };
        let built = match build_one(&source_text, source) {
            Ok(b) => b,
            Err(e) => {
                eprintln!("mzizi-css: {e}");
                return ExitCode::FAILURE;
            }
        };
        let out_path = dist.join(output);
        if check {
            let committed = fs::read_to_string(&out_path).unwrap_or_default();
            if committed != built {
                drift.push(out_path.display().to_string());
            }
        } else {
            if let Err(e) = fs::create_dir_all(&dist).and_then(|()| fs::write(&out_path, &built)) {
                eprintln!("mzizi-css: cannot write {}: {e}", out_path.display());
                return ExitCode::FAILURE;
            }
            println!(
                "mzizi-css: wrote {} ({} bytes)",
                out_path.display(),
                built.len()
            );
        }
    }

    if check {
        if drift.is_empty() {
            println!("mzizi-css: styles/pattern/dist is up to date");
            ExitCode::SUCCESS
        } else {
            for p in &drift {
                eprintln!("mzizi-css: {p} has drifted from its source; run pnpm pattern:build");
            }
            ExitCode::FAILURE
        }
    } else {
        ExitCode::SUCCESS
    }
}

#[cfg(test)]
mod tests {
    use super::parse_mode;

    fn mode(args: &[&str]) -> Result<bool, String> {
        parse_mode(args.iter().map(|a| a.to_string()))
    }

    #[test]
    fn no_arguments_builds() {
        assert_eq!(mode(&[]), Ok(false));
    }

    #[test]
    fn check_flag_checks() {
        assert_eq!(mode(&["--check"]), Ok(true));
    }

    #[test]
    fn typos_and_extra_arguments_are_refused() {
        for args in [&["--chekc"][..], &["check"], &["--check", "x"], &["build"]] {
            assert!(mode(args).is_err(), "{args:?} should be refused");
        }
    }
}
